    function handleOverlayClick(event) {
      if (event.target === document.getElementById('editModal')) {
        closeModal();
      }
    }

    function saveChanges() {
      if (currentField === 'identity') {
        const newName = document.getElementById('input-name').value.trim();
        const newEmail = document.getElementById('input-email').value.trim();
        if (newName) dataStore.name = newName;
        if (newEmail) dataStore.email = newEmail;
        document.getElementById('display-name').innerText = dataStore.name;
        document.getElementById('display-email').innerText = dataStore.email;
      } else if (currentField === 'phone') {
        const newPhone = document.getElementById('input-phone').value.trim();
        if (newPhone) dataStore.phone = newPhone;
        document.getElementById('display-phone').innerText = dataStore.phone;
      } else if (currentField === 'iban') {
        const newIban = document.getElementById('input-iban').value.trim();
        if (newIban) dataStore.iban = newIban;
        document.getElementById('display-iban').innerText = dataStore.iban;
      }

      closeModal();
      showToast();
    }

    function showToast() {
      const toast = document.getElementById('toast');
      toast.classList.add('show');
      setTimeout(() => {
        toast.classList.remove('show');
